// E-learning catalogue. Course files are generated by scripts/build-elearning-course.mjs:
// they contain the texts and questions but never the correct answers (kept by the server).

export const PASS = 80;

export interface CourseModule { id: string; title: string; minutes: number }
export interface CourseStep {
  id: string;
  kind: 'chapitre' | 'examen' | 'final';
  part: string | null;
  title: string;
  modules: CourseModule[];
}
export interface Question { question: string; answers: string[] }
export interface Quiz { title: string; questions: Question[] }
export interface ModuleContent { objectives: string[]; text: string; quizzes: Quiz[] }
export interface Course {
  id: string;
  title: string;
  certTitle: string;
  domain: string;
  summary: string;
  parts: { id: string; title: string }[];
  steps: CourseStep[];
  modules: Record<string, ModuleContent>;
}

export const COURSES: { id: string; load: () => Promise<Course> }[] = [
  { id: 'cartographie-geomatique', load: () => import('./cartographie-geomatique.json').then((m) => m.default as Course) }
];

